// Aus allen Anhaengen das erste PDF herausziehen und einheitlich als binary "pdf"
// ablegen. Mails ohne PDF fallen raus.
//
// Kopfzeilen kommen je nach Gmail-Knoten-Modus als Objekt, als Array oder gar
// nicht - und der Wert enthaelt oft den Feldnamen gleich mit ("From: ...").
// Umlaute stecken zusaetzlich in RFC-2047-Kodierung (=?UTF-8?Q?...?=).

function mimeText(s) {
  let t = String(s || '');
  // Zwei aneinandergrenzende kodierte Woerter durch Leerraum getrennt gehoeren
  // zusammen - der Leerraum dazwischen ist kein Inhalt.
  t = t.replace(/\?=\s+=\?/g, '?==?');
  return t.replace(/=\?([A-Za-z0-9_\-]+)\?([BbQq])\?([^?]*)\?=/g, (treffer, satz, art, inhalt) => {
    try {
      const kodierung = /iso-8859|windows-1252|latin/i.test(satz) ? 'latin1' : 'utf8';
      if (art.toUpperCase() === 'B') {
        return Buffer.from(inhalt, 'base64').toString(kodierung);
      }
      const roh = inhalt.replace(/_/g, ' ')
        .replace(/=([0-9A-Fa-f]{2})/g, (x, hex) => String.fromCharCode(parseInt(hex, 16)));
      return Buffer.from(roh, 'binary').toString(kodierung);
    } catch (e) { return treffer; }
  });
}

function saeubern(wert, feld) {
  // "From: Google <<EMAIL>>" -> "Google <<EMAIL>>"
  const ohnePraefix = String(wert || '').replace(new RegExp('^\\s*' + feld + '\\s*:\\s*', 'i'), '');
  return mimeText(ohnePraefix).trim();
}

function kopf(j, feld) {
  const p = j.payload || {};
  // a) Array-Form: payload.headers = [{name, value}, ...]
  if (Array.isArray(p.headers)) {
    const t = p.headers.find(h => String(h.name || '').toLowerCase() === feld);
    if (t && t.value) { return saeubern(t.value, feld); }
  }
  // b) Objekt-Form: headers = { from: "...", subject: "..." }
  const kandidaten = [j.headers, p.headers, j];
  for (const q of kandidaten) {
    if (!q || typeof q !== 'object') { continue; }
    for (const k of Object.keys(q)) {
      if (k.toLowerCase() !== feld) { continue; }
      const v = q[k];
      if (typeof v === 'string') { return saeubern(v, feld); }
      // c) strukturiert: { name, address } oder { value }
      if (v && typeof v === 'object') {
        if (typeof v.value === 'string') { return saeubern(v.value, feld); }
        if (v.address) { return saeubern((v.name ? v.name + ' ' : '') + '<' + v.address + '>', feld); }
      }
    }
  }
  return '';
}

function empfangsZeit(j) {
  if (j.internalDate) { return new Date(Number(j.internalDate)).toISOString(); }
  const roh = kopf(j, 'date') || j.date || '';
  const t = roh ? new Date(roh) : null;
  return (t && !isNaN(t.getTime())) ? t.toISOString() : null;
}

const raus = [];

for (const item of $input.all()) {
  const bin = item.binary || {};
  const key = Object.keys(bin).find(k => {
    const b = bin[k] || {};
    const typ  = String(b.mimeType || '').toLowerCase();
    const name = String(b.fileName || '').toLowerCase();
    return typ.includes('pdf') || name.endsWith('.pdf');
  });

  if (!key) { continue; }

  const j = item.json || {};
  raus.push({
    json: {
      id:        String(j.id || ''),
      thread:    String(j.threadId || j.id || ''),
      von:       kopf(j, 'from'),
      betreff:   kopf(j, 'subject'),
      empfangen: empfangsZeit(j),
      pdf_datei: String(bin[key].fileName || 'rechnung.pdf')
    },
    binary: { pdf: bin[key] }
  });
}

return raus;

// Modellantwort auswerten, Dateinamen nach Elias' Konvention bauen und das
// PDF-Binary wieder anhaengen.
// Konvention: JJJJ-MM-TT_Anbieter_Belegnummer_Leistung_BetragWAEHRUNG.pdf

const quelle = $('PDF finden').all();

function sauber(s) {
  return String(s || '')
    .replace(/[ä]/gi, 'ae').replace(/[ö]/gi, 'oe').replace(/[ü]/gi, 'ue').replace(/ß/g, 'ss')
    .replace(/[^A-Za-z0-9\-]/g, '-')
    .replace(/-+/g, '-')
    .replace(/^-|-$/g, '');
}

// Anbieter -> Notion-Kategorie. Alles Unbekannte bleibt Tools/Software.
const KATEGORIE = {
  hetzner: 'Hosting', ionos: 'Hosting', netcup: 'Hosting', strato: 'Hosting',
  anthropic: 'Tools/Software', google: 'Tools/Software', notion: 'Tools/Software',
  apple: 'Tools/Software', openai: 'Tools/Software', stripe: 'Tools/Software'
};

const gesehen = new Set();

return $input.all().map((item, i) => {
  const original = quelle[i] || {};
  const basis = original.json || {};

  let antwort = '';
  try { antwort = (item.json.content && item.json.content[0]) ? item.json.content[0].text : ''; } catch (e) {}

  let d = {};
  try {
    const t = antwort.match(/\{[\s\S]*\}/);
    d = t ? JSON.parse(t[0]) : {};
  } catch (e) { d = {}; }

  const brutto = (d.brutto === '' || d.brutto === null || d.brutto === undefined) ? null : Number(d.brutto);
  const waehrung = String(d.waehrung || 'EUR').toUpperCase();
  let lesbar = Boolean(d.sicher) && d.rechnungsdatum && d.anbieter && brutto !== null && !isNaN(brutto);

  // Quartal aus dem RECHNUNGSDATUM, nicht aus dem Empfangsdatum
  let quartal = '';
  if (d.rechnungsdatum && /^\d{4}-\d{2}-\d{2}$/.test(d.rechnungsdatum)) {
    const dt = new Date(d.rechnungsdatum + 'T12:00:00Z');
    quartal = dt.getUTCFullYear() + '-Q' + (Math.floor(dt.getUTCMonth() / 3) + 1);
  }

  // Doppelte Mails zum selben Vorgang: Anbieter schicken oft Rechnung UND
  // Zahlungsbeleg mit demselben PDF. Schluessel ohne Trennzeichen in der
  // Belegnummer, sonst zaehlt "9BF0758D-4861400" als eigener Vorgang.
  const schluessel = [
    sauber(d.anbieter).toLowerCase(),
    d.rechnungsdatum || '',
    brutto === null ? '' : brutto.toFixed(2),
    String(d.belegnummer || '').replace(/[^A-Za-z0-9]/g, '').toUpperCase()
  ].join('|');

  let duplikat = false;
  if (lesbar) {
    if (gesehen.has(schluessel)) { duplikat = true; lesbar = false; }
    else { gesehen.add(schluessel); }
  }

  const betragText = brutto === null ? '' : brutto.toFixed(2).replace('.', ',');
  const dateiname = lesbar
    ? [d.rechnungsdatum, sauber(d.anbieter), sauber(d.belegnummer || 'ohne-Nr'), sauber(d.leistung || 'Leistung'), betragText + waehrung].join('_') + '.pdf'
    : basis.pdf_datei;

  const anbieterKlein = String(d.anbieter || '').toLowerCase();
  const kategorie = Object.keys(KATEGORIE).find(k => anbieterKlein.includes(k));

  let hinweis = '';
  if (duplikat)     { hinweis = 'Duplikat: derselbe Vorgang kam in diesem Lauf schon vor'; }
  else if (!lesbar) { hinweis = 'Daten unvollstaendig oder unsicher - bitte von Hand pruefen'; }

  return {
    json: {
      ...basis,
      rechnungsdatum: d.rechnungsdatum || null,
      anbieter:       d.anbieter || '',
      belegnummer:    d.belegnummer || '',
      leistung:       d.leistung || '',
      brutto:         brutto,
      ust_betrag:     (d.ust_betrag === '' || d.ust_betrag == null) ? null : Number(d.ust_betrag),
      ust_satz:       d.ust_satz === undefined ? '' : String(d.ust_satz),
      netto:          (d.netto === '' || d.netto == null) ? null : Number(d.netto),
      waehrung:       waehrung,
      fremdwaehrung:  waehrung !== 'EUR',
      kategorie:      kategorie ? KATEGORIE[kategorie] : 'Tools/Software',
      ist_gutschrift: Boolean(d.ist_gutschrift),
      quartal,
      dateiname,
      vollstaendig:   lesbar,
      duplikat,
      // Duplikate werden nicht erfasst, die Mail wird aber trotzdem abgehakt,
      // sonst laeuft sie in jedem Durchgang erneut durch das Modell.
      markieren:      lesbar || duplikat,
      hinweis
    },
    binary: original.binary
  };
});

// Der Drive-Knoten ersetzt den Datensatz durch die Datei-Antwort.
// Originaldaten zurueckholen und den Drive-Link ergaenzen.
const quelle = $('Daten aufbereiten').all().map(i => i.json).filter(j => j.vollstaendig);

return $input.all().map((item, i) => {
  const o = quelle[i] || {};
  const drive = item.json || {};
  return { json: {
    ...o,
    drive_id:   drive.id || '',
    drive_link: drive.webViewLink || (drive.id ? 'https://drive.google.com/file/d/' + drive.id + '/view' : ''),
    upload_ok:  Boolean(drive.id)
  }};
});

