={{ JSON.stringify((() => {
const eur = !$json.fremdwaehrung;
  const betragTxt = String($json.brutto).replace('.', ',') + ' ' + $json.waehrung;

  // USt-Satz nur setzen, wenn er wirklich auf dem Beleg steht. Frueher stand
  // hier ein 19-Prozent-Default - der hat bei jedem unklaren Beleg falsche
  // Vorsteuer erzeugt.
  const satzKarte = { '19': '19 %', '7': '7 %', '0': '0 %', 'reverse-charge': 'Reverse Charge' };
  const satz = satzKarte[String($json.ust_satz)] || null;

  const props = {
    'Beschreibung': { title: [{ text: { content: ($json.anbieter + ' – ' + ($json.leistung || 'Leistung')
        + ($json.belegnummer ? ' (' + $json.belegnummer + ')' : '')
        + (eur ? '' : ' [' + betragTxt + ']')).substring(0, 1900) } }] },
    'Lieferant':    { rich_text: [{ text: { content: String($json.anbieter || '') } }] },
    'Betrag':       { number: $json.brutto },
    'Betrag netto': { number: $json.netto },
    'Kategorie':    { select: { name: $json.kategorie || 'Tools/Software' } },
    'Datum':        { date: { start: $json.rechnungsdatum } },
    'In sevDesk erfasst': { checkbox: false },
    'Wiederkehrend':      { checkbox: false }
  };

  if (satz) { props['USt-Satz'] = { select: { name: satz } }; }

  // Beleg als Datei-Eigenschaft, damit die Ansicht "Ohne Beleg" stimmt.
  if ($json.drive_link) {
    props['Beleg'] = { files: [{ name: String($json.dateiname).substring(0, 100),
                                 external: { url: $json.drive_link } }] };
  }

  const zeilen = [
    { type: 'text', text: { content: 'Automatisch erfasst durch den Rechnungspfad. Beleg: ' } },
    { type: 'text', text: { content: $json.dateiname, link: $json.drive_link ? { url: $json.drive_link } : null } },
    { type: 'text', text: { content: '\nUSt laut Beleg: '
        + ($json.ust_betrag === null ? 'nicht ausgewiesen' : $json.ust_betrag + ' ' + $json.waehrung)
        + (satz ? '' : '\nUSt-SATZ NICHT ERKANNT - bitte selbst setzen, sonst rechnet die Vorsteuer-Formel nichts.')
        + (eur ? '' : '\nFREMDWAEHRUNG: Der Beleg lautet auf ' + betragTxt + '. Im Feld Betrag steht dieser Wert unveraendert - den tatsaechlich belasteten Euro-Betrag bitte aus dem Kontoauszug nachtragen.')
        + ($json.ist_gutschrift ? '\nGUTSCHRIFT - mindert die Vorsteuer.' : '')
        + '\nKategorie ist geraten, bitte pruefen.' } }
  ];

  return { parent: { database_id: '<NOTION_ID>' }, properties: props,
           children: [{ object: 'block', type: 'paragraph', paragraph: { rich_text: zeilen } }] };
})()) }}

