const labelKarte = { '2026-Q2': true, '2026-Q3': true, '2026-Q4': true };
  const quartalsLabel = ($json.vollstaendig && labelKarte[$json.quartal])
    ? ' + Finanzen und Belege/' + $json.quartal : '';

  const labelText = $json.vollstaendig
    ? ('Finanzen und Belege' + quartalsLabel + ' · ' + $json.dateiname)
    : ($json.duplikat ? 'Finanzen und Belege (Duplikat, nicht erfasst)' : 'nicht verarbeitet');

  const grund = $json.vollstaendig
    ? ('Beleg erfasst: ' + $json.anbieter + ', ' + $json.brutto + ' ' + $json.waehrung
       + ', Rechnungsdatum ' + $json.rechnungsdatum
       + ($json.upload_ok ? ', in Drive abgelegt' : ', DRIVE-UPLOAD FEHLGESCHLAGEN')
       + ($json.fremdwaehrung ? ' – FREMDWAEHRUNG, Euro-Betrag nachtragen' : ''))
    : ($json.hinweis || 'Rechnungsdaten nicht lesbar');

  return { parent: { database_id: '<NOTION_ID>' }, properties: {
    'Betreff':         { title: [{ text: { content: ('[BELEG] ' + String($json.betreff || '')).substring(0, 1900) } }] },
    'Absender':        { rich_text: [{ text: { content: String($json.von || '') } }] },
    'Empfangen':       $json.empfangen ? { date: { start: $json.empfangen } } : { date: null },
    'Aktion':          { select: { name: $json.vollstaendig ? 'Labeln' : ($json.duplikat ? 'Uebersprungen' : 'Eskaliert') } },
    'Label':           { rich_text: [{ text: { content: labelText } }] },
    'Entschieden von': { select: { name: $json.vollstaendig ? 'Claude' : 'Unsicher' } },
    'Confidence':      { number: $json.vollstaendig ? 1 : 0 },
    'Begruendung':     { rich_text: [{ text: { content: String(grund).substring(0, 1900) } }] },
    'Status':          { select: { name: $json.vollstaendig ? 'Ausgefuehrt' : 'Vorgeschlagen' } },
    'Thread-ID':       { rich_text: [{ text: { content: String($json.thread || '') } }] },
    'Lauf':            { date: { start: new Date().toISOString() } }
  } };
})()) }}
